  "landing.one.s7": "Tiến bộ",
  "landing.faq.title": "Các câu hỏi thường gặp",
  "landing.faq.q1": "Second Brain có phải chỉ là một chatbot không?",
  "landing.faq.a1": "Không. Đây là một môi trường học tập cá nhân: hệ thống hiểu nội dung của bạn, giảng dạy và ghi nhớ tiến trình của bạn theo thời gian.",
  "landing.faq.q2": "Tôi có thể làm việc với nhiều tệp PDF và tài liệu không?",
  "landing.faq.a2": "Có. Bạn có thể nhóm các tệp PDF, ảnh, bản quét và ghi chú thành một chủ đề hoàn chỉnh và học từ toàn bộ tập hợp đó, thay vì chỉ một tệp duy nhất.",
  "landing.faq.q3": "Tôi có thể làm gì với AI Professor?",
  "landing.faq.a3": "Được giảng dạy, yêu cầu giải thích, thảo luận, chạy các buổi hướng dẫn và luyện tập với các bài tập — được điều chỉnh theo trình độ của bạn.",
  "landing.faq.q4": "Tôi có thể trò chuyện to tiếng với Giáo sư AI không?",
  "landing.faq.a4": "Có. Trò chuyện bằng lời nói, bài tập miệng và kỳ thi vấn đáp giúp bạn luyện tập thành tiếng.",
  "landing.faq.q5": "Bản sao số (Digital Twin) là gì?",
  "landing.faq.a5": "Bộ nhớ cá nhân hóa về quá trình học tập của bạn — những gì bạn hiểu, thành thạo, quên và hướng tới.",
  "landing.faq.q6": "Bộ nhớ và ôn tập hoạt động như thế nào?",
  "landing.faq.a6": "Công cụ lặp lại ngắt quãng (FSRS) lên lịch ôn tập vào thời điểm thích hợp giúp bạn ghi nhớ nhiều hơn với ít nỗ lực hơn.",
  "landing.faq.q7": "Tôi có thể sử dụng Second Brain cho công việc học tập của mình không?",
  "landing.faq.a7": "Có. Không gian làm việc học thuật hướng dẫn các phòng thí nghiệm, bài tập về nhà, báo cáo và nhiều hơn nữa — dạy phương pháp chứ không chỉ đáp án.",
  "landing.faq.q8": "Việc học ngôn ngữ hoạt động như thế nào?",
  "landing.faq.a8": "Sự đắm chìm, trò chuyện, luyện tập nói và shadowing — cùng sự hỗ trợ hiểu ngôn ngữ trong chương trình giảng dạy của riêng bạn.",
  "landing.faq.q9": "Dữ liệu của tôi được bảo vệ như thế nào?",
  "landing.faq.a9": "Dữ liệu học tập cung cấp năng lượng cho trải nghiệm của bạn. Bạn kiểm soát tài khoản của mình và có thể quản lý dữ liệu từ hồ sơ của mình.",
  "landing.pricing.title": "Chọn cấp độ học tập của bạn",
