  "landing12.story.kicker": "Một sản phẩm, một trải nghiệm",
  "landing12.story.title": "Theo dõi kiến thức di chuyển trong toàn hệ thống",
  "landing12.story.lead": "Một nguồn không dừng ở lưu trữ. Phần trình diễn này theo cùng ngữ cảnh từ tài liệu đến hiểu, luyện tập, ôn tập và sản xuất học thuật.",
  "landing12.story.documents.title": "Tài liệu trở thành kiến thức dùng được",
  "landing12.story.documents.short": "Tài liệu",
  "landing12.story.documents.desc": "Thư viện nhận nguồn. Trí tuệ Tài liệu đọc, trích xuất khái niệm và chuẩn bị câu hỏi có căn cứ mà không bịa ra tiến độ.",
  "landing12.story.brain.title": "Khái niệm tham gia bản đồ nhận thức kết nối",
  "landing12.story.brain.short": "Bộ não của tôi",
  "landing12.story.brain.desc": "Bản sao nhận thức làm rõ khái niệm, mối quan hệ, điểm mạnh và điểm yếu. Ví dụ công khai này chỉ để minh họa, không phải điểm thực của người học.",
  "landing12.story.professor.title": "Giáo sư dạy từ cùng một ngữ cảnh",
  "landing12.story.professor.short": "Giáo sư AI",
  "landing12.story.professor.desc": "Tài liệu, khái niệm đích và mục tiêu học tập đi cùng phiên. Trải nghiệm có thể trở thành giải thích, bài học, câu hỏi hoặc bài luyện có hướng dẫn.",
  "landing12.story.oral.title": "Sự hiểu biết trở thành luyện nói",
  "landing12.story.oral.short": "Nói và Giọng nói",
  "landing12.story.oral.desc": "Lắng nghe, chuyển lời nói thành văn bản và phản hồi là các trạng thái riêng, dễ đọc. Bản chép lời luôn hiển thị; không có dạng sóng trang trí giả vờ đo giọng nói.",
  "landing12.story.review.title": "Một ý tưởng dễ quên trở thành lượt ôn tập",
  "landing12.story.review.short": "Ôn tập",
  "landing12.story.review.desc": "Công cụ ôn tập củng cố kiến thức đúng lúc. Ngày hiển thị ở đây rõ ràng chỉ là minh họa, không phải lịch thật.",
  "landing12.story.workspace.title": "Kiến thức trở thành sản phẩm",
  "landing12.story.workspace.short": "Không gian làm việc",
  "landing12.story.workspace.desc": "Không gian Làm việc Học thuật giữ dàn ý, văn bản, nguồn và trích dẫn bên nhau trong khi trợ lý theo ngữ cảnh hỗ trợ công việc của chính người học.",
  "landing12.story.sharedContext": "Ngữ cảnh dùng chung",
  "landing12.story.traceability": "Truy xuất nguồn gốc",
  "landing12.story.outcome": "Tôi đưa thông tin → Second Brain hiểu → dạy tôi → giúp tôi luyện tập → giúp tôi ghi nhớ → giúp tôi sử dụng.",
  "landing12.story.nba": "Sau đó hệ thống đề xuất một hành động tiếp theo rõ ràng, có thể giải thích thay vì bỏ mặc tôi trong bảng điều khiển.",
