  "landing12.faq.a1": "Hệ thống học tập thông minh cá nhân kết nối câu hỏi, nguồn, giảng dạy, luyện tập, bộ nhớ và công việc học thuật trong một ngữ cảnh.",
  "landing12.faq.q2": "Nó chỉ đơn giản là chatbot?",
  "landing12.faq.a2": "Không. Hội thoại là một giao diện. Cùng một phiên có thể trở thành bài học, bài tập nói, câu hỏi tài liệu có nguồn, lượt ôn tập hoặc hành động trong Không gian làm việc.",
  "landing12.faq.q3": "Bộ não của tôi hoạt động thế nào?",
  "landing12.faq.a3": "Nó hiển thị khái niệm, mối quan hệ, bằng chứng thành thạo, bộ nhớ và lịch sử học tập. Chế độ xem thích ứng theo độ trưởng thành của dữ liệu hiện có.",
  "landing12.faq.q4": "Tôi có thể dùng tài liệu của mình không?",
  "landing12.faq.a4": "Có. Thư viện nhận tệp và bản quét được hỗ trợ, hiển thị trạng thái xử lý thực, trích xuất khái niệm và hỗ trợ câu hỏi có căn cứ cùng nội dung chuyển đổi.",
  "landing12.faq.q5": "Tôi có thể học một ngôn ngữ không?",
  "landing12.faq.a5": "Có. Công cụ Ngôn ngữ Đời thực kết hợp chương trình CEFR, học ngôn ngữ rõ ràng, Nhiệm vụ Thế giới Thực, luyện nói, khắc phục có trọng tâm, ôn tập và bằng chứng Can-Do.",
  "landing12.faq.q6": "Giáo sư AI hoạt động thế nào?",
  "landing12.faq.a6": "Giáo sư dùng ngữ cảnh đang hoạt động của người học và có thể giải thích, dạy, hỏi, đánh giá hoặc luyện tập trong khi giữ nguyên Phiên Trải nghiệm.",
  "landing12.faq.q7": "Ôn tập hoạt động thế nào?",
  "landing12.faq.a7": "Ôn tập dùng lịch sử thực và lặp lại ngắt quãng để ưu tiên kiến thức có nguy cơ bị quên. Ôn tập không dùng AI vẫn khả dụng độc lập với hạn mức AI.",
  "landing12.faq.q8": "Có những ngôn ngữ nào?",
  "landing12.faq.a8": "Danh mục dùng chung hiện có 34 ngôn ngữ học tập. Ngôn ngữ giao diện và ngôn ngữ học luôn là hai lựa chọn riêng.",
  "landing12.faq.q9": "Nghiên cứu có tìm trên Web không?",
  "landing12.faq.a9": "Nghiên cứu hiện có thể hoạt động trong Bộ não của tôi và Thư viện. Nhà cung cấp Web bên ngoài chưa được cấu hình trong bản triển khai hiện tại nên Trang đích không tuyên bố có chức năng đó.",
  "landing12.faq.q10": "Dữ liệu của tôi có riêng tư không?",
  "landing12.faq.a10": "Các kiểm soát đã xác thực bao gồm bộ nhớ AI, tài liệu, sự đồng ý, xuất dữ liệu và xóa tài khoản. Trang này không thêm lời hứa pháp lý hoặc hạ tầng ngoài những kiểm soát đó.",
  "landing12.faq.q11": "Miễn phí, Pro và Max khác nhau thế nào?",
  "landing12.faq.a11": "Đó là ba cấp gói cá nhân trong danh mục hệ thống hỗ trợ. Giá, hạn mức và quyền lợi cuối cùng sẽ được cấu hình sau beta công khai.",
  "landing12.faq.q12": "Tôi có thể dùng Second Brain ở đâu?",
  "landing12.faq.a12": "Trải nghiệm Web khả dụng trong ứng dụng này. Android và iOS đã sẵn sàng về kỹ thuật nhưng chưa có liên kết cửa hàng công khai; bản phân phối Windows và macOS vẫn sắp ra mắt.",
